  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_by_id = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        children[n['id']] = []
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    retained = set(node_by_id.keys())
    candidates = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removal_order = []
    for n in candidates:
        if not n['removable']:
            continue
        has_retained_child = any(cid in retained for cid in children.get(n['id'], []))
        if has_retained_child:
            continue
        sym = n['symbol']
        if sym in required_symbols:
            count = sum(1 for rid in retained if node_by_id[rid]['symbol'] == sym)
            if count == 1:
                continue
        retained.remove(n['id'])
        removal_order.append(n['id'])
    sorted_retained = sorted(retained)
    return {'retained': sorted_retained, 'removal_order': removal_order}
